#include <iostream>
#include <string>
#include <cctype>

int main()
{
    std::string crop = "maize";
    std::cout << crop.size() << " " << crop[0] << " " << crop.substr(1, 3) << "\n";
    for (char& c : crop) c = std::toupper(c);
    std::cout << crop + "!" << "\n";
    return 0;
}

