exercises.solution:
#include <string>
#include <cctype>

std::string initials(std::string first, std::string last)
{
    std::string r;
    r += (char)std::toupper(first[0]);
    r += '.';
    r += (char)std::toupper(last[0]);
    r += '.';
    return r;
}
